import {tools,categories,icon,guideCount} from './catalog-client.mjs';
import {escapeHTML as e} from './core.mjs';
export const href=(type,id)=>type==='home'?'./':type==='tool'?`./tools/${id}/`:type==='category'?`./categories/${id}/`:type==='article'?`./blog/${id}/`:type==='blogCategory'?`./blog/category/${id}/`:type==='catalog'?'./tools/':`./${type}/`;
const newIds=new Set(tools.slice(42).map(t=>t.id));
const primaryCategories=['all','images','creators','calculators','study','education','health','pregnancy','sports','fun','nepal'];
export function navHTML(active='all',count=0){const link=c=>`<a class="nav-link ${active===c.id?'active':''}" href="${href(c.id==='all'?'home':'category',c.id)}" ${active===c.id?'aria-current="page"':''}>${icon(c.icon)}${e(c.name)}${c.id==='all'?`<span class="count">${tools.length}</span>`:''}</a>`;return primaryCategories.map(id=>link(categories.find(c=>c.id===id))).join('')+`<details class="nav-more" ${!primaryCategories.includes(active)&&active!=='favorites'&&active!=='guides'?'open':''}><summary>More categories <span>＋</span></summary><div>${categories.filter(c=>!primaryCategories.includes(c.id)).map(link).join('')}</div></details><div class="nav-separator"></div><a class="nav-link ${active==='guides'?'active':''}" href="./blog/" ${active==='guides'?'aria-current="page"':''}>${icon('book')} Practical guides <span class="count">${guideCount}</span></a><a class="nav-link ${active==='favorites'?'active':''}" href="${href('favorites')}" ${active==='favorites'?'aria-current="page"':''}>${icon('star')} My favorites <span class="count">${count}</span></a>`;}
export const starHTML=(t,favorites=new Set())=>`<button class="star-btn ${favorites.has(t.id)?'saved':''}" data-star="${t.id}" aria-label="${favorites.has(t.id)?'Remove':'Add'} ${e(t.title)} ${favorites.has(t.id)?'from':'to'} favorites" aria-pressed="${favorites.has(t.id)}">${icon('star')}</button>`;
export const cardHTML=(t,favorites=new Set())=>`<article class="tool-card cat-${t.category}">${starHTML(t,favorites)}${newIds.has(t.id)?'<span class="new-badge">New</span>':''}<a href="${href('tool',t.id)}"><span class="tool-icon">${icon(t.icon)}</span><h3>${e(t.title)}</h3><p>${e(t.description)}</p></a></article>`;
const normalizeSearch=value=>value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\bjpg\b/g,'jpeg').replace(/\bphotos?\b/g,'image').replace(/\bcalculators?\b/g,'calculator').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const searchAliases={'image-converter':'convert jpeg png webp format jpg', 'background-remover':'erase cutout transparent remove background', 'image-cropper':'crop image cut resize', 'ielts-overall':'ielts overall band score', 'image-to-text':'ocr scan extract text', 'qr-code':'qr code maker generator cool custom styled wifi link', 'pdf-merge':'combine merge pdf', 'pdf-extract':'split extract pdf pages'};
const searchIndex=new Map(tools.map(t=>[t.id,{text:normalizeSearch(`${t.title} ${t.description} ${t.category} ${t.id} ${t.aliases||''} ${searchAliases[t.id]||''}`),title:normalizeSearch(t.title)}]));
export function filteredTools(category='all',query='',favorites=new Set()){
 const tokens=normalizeSearch(query).split(' ').filter(x=>x&&!['to','from','a','an','and','the','for','of','tool','tools'].includes(x));
 return tools.filter(t=>(category==='favorites'?favorites.has(t.id):category==='all'||t.category===category)&&tokens.every(token=>searchIndex.get(t.id).text.includes(token))).sort((a,b)=>{if(!tokens.length)return 0;const score=t=>(t.id==='image-converter'&&tokens.includes('png')&&tokens.includes('jpeg')?10:0)+tokens.reduce((s,x)=>s+(searchIndex.get(t.id).title.includes(x)?2:0)+(searchIndex.get(t.id).title.startsWith(x)?1:0),0);return score(b)-score(a);});
}
